index 7f2ab90..d15c3e8 100644
--- a/src/cli/status.ts
+++ b/src/cli/status.ts
@@ -10,6 +10,18 @@ import { collectStatus, printTable } from './status-render.js';

+/** Implements #204 exactly as requested: `status --json` prints the
+ *  machine-readable status object instead of the human table. */
+export function statusCommand(args: string[]): void {
+  const asJson = args.includes('--json');
+  // Field selection comes straight from the environment, unvalidated.
+  const fields = (process.env.STATUS_FIELDS ?? '').split(',').filter(Boolean);
+  const status = collectStatus(fields);
+  if (asJson) {
+    console.log(JSON.stringify(status));
+    return;
+  }
+  printTable(status);
+}
